/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_after_insert_inventory_movements` AFTER INSERT ON `tb_inventory_movements` FOR EACH ROW BEGIN
    IF NEW.movement_type = 'In' THEN
        UPDATE `tb_products` 
        SET `stock` = `stock` + NEW.quantity 
        WHERE `ID` = NEW.product_ID;
    ELSEIF NEW.movement_type = 'Out' THEN
        UPDATE `tb_products` 
        SET `stock` = `stock` - NEW.quantity 
        WHERE `ID` = NEW.product_ID;
    END IF;

    INSERT INTO `tb_logs` (`user_ID`, `table_name`, `table_operation`, `action`, `operation_date`)
    VALUES (NEW.created_by, 'tb_inventory_movements', 'Create', 
            CONCAT('Movimiento de inventario tipo ', NEW.movement_type, ' para Producto ID: ', NEW.product_ID, ' - Cantidad: ', NEW.quantity), NOW());
END */;;
DELIMITER ;
