/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_before_insert` BEFORE INSERT ON `tb_people` FOR EACH ROW BEGIN
    -- Limpieza de espacios en blanco en campos de texto
    SET NEW.given_names = TRIM(NEW.given_names);
    SET NEW.family_names = TRIM(NEW.family_names);
    SET NEW.courtesy_title = TRIM(NEW.courtesy_title);
    SET NEW.phone = TRIM(NEW.phone);
    
    -- Si el country_code viene en minúsculas, convertir a mayúsculas (ej. 'mx' -> 'MX')
    IF NEW.country_code IS NOT NULL THEN
        SET NEW.country_code = UPPER(TRIM(NEW.country_code));
    END IF;

    -- Validar que la fecha de nacimiento no sea futura
    IF NEW.birth_date IS NOT NULL AND NEW.birth_date > CURDATE() THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: La fecha de nacimiento no puede ser una fecha futura.';
    END IF;

    -- Validar que la persona no tenga más de 120 años
    IF NEW.birth_date IS NOT NULL AND NEW.birth_date < DATE_SUB(CURDATE(), INTERVAL 120 YEAR) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: La fecha de nacimiento no es válida (supera los 120 años).';
    END IF;
END */;;
DELIMITER ;
