/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_after_delete` AFTER DELETE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (`user_ID`, `action`, `creation_date`)
    VALUES (
        OLD.`user_ID`,
        CONCAT('Persona eliminada ID: ', OLD.`person_ID`, ' - Nombre: ', OLD.`given_names`, ' ', COALESCE(OLD.`family_names`, '')),
        NOW()
    );
END */;;
