/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_addresses_single_default_update` BEFORE UPDATE ON `tb_user_addresses` FOR EACH ROW BEGIN
    IF NEW.is_default = b'1' AND OLD.is_default = b'0' THEN
        UPDATE `tb_user_addresses`
        SET `is_default` = b'0'
        WHERE `user_ID` = NEW.user_ID 
          AND `ID` <> NEW.ID;
    END IF;
END */;;
