/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_addresses_ensure_default_after_delete` AFTER DELETE ON `tb_user_addresses` FOR EACH ROW BEGIN
    DECLARE next_default_id BIGINT;

    IF OLD.is_default = b'1' THEN
        -- Buscar la dirección más reciente restante del usuario
        SELECT `ID` INTO next_default_id
        FROM `tb_user_addresses`
        WHERE `user_ID` = OLD.user_ID AND `status` = b'1'
        ORDER BY `creation_date` DESC
        LIMIT 1;

        -- Si existe otra dirección, marcarla como predeterminada
        IF next_default_id IS NOT NULL THEN
            UPDATE `tb_user_addresses`
            SET `is_default` = b'1'
            WHERE `ID` = next_default_id;
        END IF;
    END IF;
END */;;
DELIMITER ;
