/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payment_methods_types_after_update` AFTER UPDATE ON `tbc_payment_methods_types` FOR EACH ROW BEGIN
    -- Detecta cambio de código o descripción
    IF OLD.`code` <> NEW.`code` OR OLD.`description` <> NEW.`description` THEN
        INSERT INTO `tb_logs` (`user_ID`, `action`, `creation_date`)
        VALUES (
            1,
            CONCAT('Método de pago ID ', NEW.`ID`, ' modificado: Code ("', OLD.`code`, '" -> "', NEW.`code`, '")'),
            NOW()
        );
    END IF;

    -- Detecta cambio de estatus (bit)
    IF OLD.`status` <> NEW.`status` THEN
        INSERT INTO `tb_logs` (`user_ID`, `action`, `creation_date`)
        VALUES (
            1,
            CONCAT('Estatus cambiado en método de pago ID ', NEW.`ID`, ' a: ', NEW.`status`),
            NOW()
        );
    END IF;
END */;;
