CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_new_user`(
    IN p_email VARCHAR(150),
    IN p_username VARCHAR(100),
    IN p_password VARCHAR(255),
    IN p_degree VARCHAR(20),
    IN p_first_name VARCHAR(100),
    IN p_last_name VARCHAR(100),
    IN p_birthdate DATE,
    IN p_gender VARCHAR(20),
    IN p_country VARCHAR(5),
    IN p_phone VARCHAR(20)
)
BEGIN
    DECLARE v_user_id INT;
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- 1. Inserción en tb_users
    INSERT INTO tb_users (email, username, password) 
    VALUES (p_email, p_username, p_password);

    SET v_user_id = LAST_INSERT_ID();

    -- 2. Inserción en tb_people (usando user_ID con mayúsculas)
    INSERT INTO tb_people (
        user_ID, 
        courtesy_title, 
        given_names, 
        family_names, 
        birth_date, 
        gender, 
        country_code, 
        phone
    ) 
    VALUES (
        v_user_id, 
        p_degree, 
        p_first_name, 
        p_last_name, 
        p_birthdate, 
        p_gender, 
        p_country, 
        p_phone
    );

    -- 3. Inserción en tb_logs
    INSERT INTO tb_logs (table_name, table_operation, db_user, table_descripcion)
    VALUES ('tb_users', 'Create', CURRENT_USER(), 'Registro de nuevo usuario');

    COMMIT;
END ;;
DELIMITER ;
