CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_restore_product`(
    IN p_product_id INT
)
BEGIN
    UPDATE tb_products 
    SET status = 'ACTIVE' -- O usa: is_active = 1 / deleted = 0 según tu estructura
    WHERE id = p_product_id;
END ;;
DELIMITER ;
