CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_product`(
    IN p_product_id INT
)
BEGIN
    UPDATE tb_products 
    SET status = 'INACTIVE' -- O usa: is_active = 0 / deleted = 1 según tu estructura
    WHERE id = p_product_id;
END ;;
